void ProductionPrerequisite::resolveNames()
{
	for (UnsignedInt i = 0; i < m_prereqUnits.size(); ++i)
	{
		m_prereqUnits[i].unit = TheThingFactory->findTemplate(m_prereqUnits[i].name);
		m_prereqUnits[i].name.clear();
	}
}

// FUNCTION: BFME2 0x004F4BC0 size=98 name=?calcNumPrereqUnitsOwned@ProductionPrerequisite@@ABEHPBVPlayer@@QAH@Z evidence=N:ledger tier=A
Int ProductionPrerequisite::calcNumPrereqUnitsOwned(const Player *player, Int counts[32]) const
{
	const ThingTemplate *templates[32];
	UnsignedInt count = m_prereqUnits.size();
	if (count > 32)
		count = 32;
	for (UnsignedInt i = 0; i < count; ++i)
		templates[i] = m_prereqUnits[i].unit;
	for (Int j = count; j < 32; ++j)
		templates[j] = 0;
	player->countObjectsByThingTemplate(count, templates, false, counts, true);
	return count;
}

// FUNCTION: BFME2 0x004F4C22 size=99 name=?getAllPossibleBuildFacilityTemplates@ProductionPrerequisite@@QBEHQAPBVThingTemplate@@H@Z evidence=N:ledger tier=A
Int ProductionPrerequisite::getAllPossibleBuildFacilityTemplates(const ThingTemplate *list[], Int maxCount) const
{
	Int found = 0;
	for (Int i = 0; i < m_prereqUnits.size(); ++i)
	{
		if (i > 0 && !(m_prereqUnits[i].flags & 1))
			break;
		if (found >= maxCount)
			break;
		list[found++] = m_prereqUnits[i].unit;
	}
	return found;
}

// FUNCTION: BFME2 0x004F4C85 size=96 name=?getExistingBuildFacilityTemplate@ProductionPrerequisite@@QBEPBVThingTemplate@@PBVPlayer@@@Z evidence=N:ledger tier=B hypothesis:Z
const ThingTemplate *ProductionPrerequisite::getExistingBuildFacilityTemplate(const Player *player) const
{
	if (m_prereqUnits.size() != 0)
	{
		Int counts[32];
		Int owned = calcNumPrereqUnitsOwned(player, counts);
		for (Int i = 0; i < owned; ++i)
		{
			if (i > 0 && !(m_prereqUnits[i].flags & 1))
				return 0;
			if (counts[i] != 0)
				return m_prereqUnits[i].unit;
		}
	}
	return 0;
}

// FUNCTION: BFME2 0x004F4CE5 size=219 name=?isSatisfied@ProductionPrerequisite@@QBE_NPBVPlayer@@@Z evidence=N:ledger tier=B hypothesis:Z
Bool ProductionPrerequisite::isSatisfied(const Player *player) const
{
	if (player == 0)
		return false;

	for (UnsignedInt i = 0; i < m_prereqSciences.size(); ++i)
	{
		if (!player->hasScience(m_prereqSciences[i]))
			return false;
	}

	for (UnsignedInt i = 0; i < m_prereqUpgrades.size(); ++i)
	{
		const UpgradeTemplate *upgrade = m_prereqUpgrades[i];
		if (upgrade->getUpgradeType() != UPGRADE_TYPE_PLAYER)
			return false;
		if (!player->rva002AB87D(upgrade))
			return false;
	}

	Int counts[32];
	Int owned = calcNumPrereqUnitsOwned(player, counts);
	// An alternative adds its count to the next record and drops its own.
	for (Int i = 1; i < owned; ++i)
	{
		if (m_prereqUnits[i].flags & 1)
		{
			counts[i] += counts[i - 1];
			counts[i - 1] = -1;
		}
	}
	for (Int i = 0; i < owned; ++i)
	{
		if (counts[i] != -1 && counts[i] == 0)
			return false;
	}
	return true;
}

// FUNCTION: BFME2 0x004F4DF2 size=677 name=?getRequiresList@ProductionPrerequisite@@QBE?AVUnicodeString@@PBVPlayer@@@Z evidence=N:ledger tier=B hypothesis:Z
UnicodeString ProductionPrerequisite::getRequiresList(const Player *player) const
{
	if (player == 0)
		return UnicodeString::TheEmptyString;

	UnicodeString result = UnicodeString::TheEmptyString;

	Int counts[32];
	Int owned = calcNumPrereqUnitsOwned(player, counts);

	// Fold each alternative into the record after it and remember which ones were folded.
	Bool folded[32];
	memset(folded, 0, sizeof(folded));
	for (Int i = 1; i < owned; ++i)
	{
		if (m_prereqUnits[i].flags & 1)
		{
			counts[i] += counts[i - 1];
			counts[i - 1] = -1;
			folded[i] = true;
		}
	}

	UnicodeString text;
	Bool first = true;
	for (Int i = 0; i < owned; ++i)
	{
		if (counts[i] != 0)
			continue;

		if (folded[i])
		{
			// "<previous unit> or " goes ahead of this unit's own name.
			text = m_prereqUnits[i - 1].unit->m_displayName;
			text += L" ";
			text += TheGameText->fetch("CONTROLBAR:OrRequirement", 0);
			text += L" ";
			result += text;
		}

		text = m_prereqUnits[i].unit->m_displayName;
		if (first)
			first = false;
		else
			text += L"\n";
		result += text;
	}

	Bool havePrereqs = true;
	for (UnsignedInt i = 0; i < m_prereqSciences.size(); ++i)
	{
		if (!player->hasScience(m_prereqSciences[i]))
			havePrereqs = false;
	}
	if (!havePrereqs)
	{
		if (first)
			first = false;
		else
			text += L"\n";
		result += TheGameText->fetch("CONTROLBAR:GeneralsPromotion", 0);
	}

	havePrereqs = true;
	for (UnsignedInt i = 0; i < m_prereqUpgrades.size(); ++i)
	{
		if (!player->rva002AB87D(m_prereqUpgrades[i]))
			havePrereqs = false;
	}
	if (!havePrereqs)
	{
		if (!first)
			text += L"\n";
		result += TheGameText->fetch("CONTROLBAR:UpgradeRequired", 0);
	}

	return result;
}

